import{_ as e,C as s,o as d,c as n,j as i,E as l,a as t,a2 as r}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse('{"title":"6-dars (Mentor). Excel formulalari: Nisbiy/absolut murojaatlar, shartli va qidiruv funksiyalari","description":"","frontmatter":{"title":"6-dars (Mentor). Excel formulalari: Nisbiy/absolut murojaatlar, shartli va qidiruv funksiyalari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"week":{"n":2,"link":"/mentor/9-sinf-bi/hafta-02/"},"g":6,"title":"Excel formulalari: Nisbiy/absolut murojaatlar, shartli va qidiruv funksiyalari","lead":"Hisob-kitoblar qudrati: formulalarda absolut va nisbiy manzillar, mantiqiy shartlar (IF, SUMIF, COUNTIF) hamda mukammal XLOOKUP qidiruv mexanizmi.","slide":"/slaydlar/9-sinf-bi/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-bi/hafta-02/dars-3-test.html","student_link":"/9-sinf-bi/hafta-02/dars-3","tabs":[{"g":4,"link":"/mentor/9-sinf-bi/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/9-sinf-bi/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/9-sinf-bi/hafta-02/dars-3","current":true}],"prev":{"g":5,"title":"Professional jadval tuzish, Tidy Data va Excel Table (Ctrl+T)","link":"/mentor/9-sinf-bi/hafta-02/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-02/dars-3.md","filePath":"mentor/9-sinf-bi/hafta-02/dars-3.md"}'),u={name:"mentor/9-sinf-bi/hafta-02/dars-3.md"},c={class:"blk"},h={id:"dars-rejasi",tabindex:"-1"},m={class:"blk"},q={id:"mentor-konspekti",tabindex:"-1"},g={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},f={id:"tezkor-nazorat-savollari",tabindex:"-1"},y={class:"blk"},v={id:"uyga-vazifa",tabindex:"-1"};function _(p,a,x,O,T,A){const o=s("Icon");return d(),n("div",null,[i("div",c,[i("h2",h,[l(o,{name:"file-text"}),a[0]||(a[0]=t(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga Excelda formulalar tuzish mantiqi, nisbiy (<code>A1</code>) va absolut (<code>$A$1</code>) katak murojaatlari, asosiy statistik funksiyalar (<code>SUM</code>, <code>AVERAGE</code>, <code>COUNT</code>, <code>COUNTA</code>), shartli mantiqiy funksiyalar (<code>IF</code>, <code>COUNTIF</code>, <code>SUMIF</code>) hamda zamonaviy qidiruv va bog&#39;lash vositasi bo&#39;lgan <code>XLOOKUP</code> funksiyasini amalda qo&#39;llashni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar formulada qachon <code>$</code> belgisini (F4) ishlatishni biladi; shartli hisob-kitoblarni bajara oladi; ikkita alohida jadvalni <code>XLOOKUP</code> orqali bog&#39;lay oladi va formulalardagi xatolarni (<code>#VALUE!</code>, <code>#N/A</code>, <code>#DIV/0!</code>) to&#39;g&#39;rilash ko&#39;nikmasiga ega bo&#39;ladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan darsni takrorlash (Tidy Data va Excel Table): 10 daqiqa</li><li>Yangi mavzu: Nisbiy/absolut murojaatlar va statistik funksiyalar: 20 daqiqa</li><li>Shartli funksiyalar (<code>IF</code>, <code>COUNTIF</code>, <code>SUMIF</code>): 25 daqiqa</li><li><code>XLOOKUP</code> va xatolarni tahlil qilish amaliyoti: 15 daqiqa</li><li>Nazorat savollari va hafta xulosasi: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",m,[i("h2",q,[l(o,{name:"file-text"}),a[3]||(a[3]=t(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-nisbiy-va-absolut-murojaatlar-belgisi-va-f4" tabindex="-1">1. Nisbiy va Absolut murojaatlar ($ belgisi va F4) <a class="header-anchor" href="#_1-nisbiy-va-absolut-murojaatlar-belgisi-va-f4" aria-label="Permalink to &quot;1. Nisbiy va Absolut murojaatlar ($ belgisi va F4)&quot;">​</a></h3><p>Formulalarni pastga yoki yonga nusxalaganda katak manzillarining harakati:</p><ul><li><strong>Nisbiy murojaat (Relative: <code>A1</code>):</strong> Formulani pastga tortsangiz, u avtomatik ravishda <code>A2</code>, <code>A3</code>, <code>A4</code> bo&#39;lib o&#39;zgaradi.</li><li><strong>Absolut murojaat (Absolute: <code>$A$1</code>):</strong> Dollar belgisi ustun va qatorni &quot;qotirib&quot; (muzlatib) qo&#39;yadi. Formulani qayerga nusxalasangiz ham, u faqat <code>A1</code> katagiga murojaat qiladi. <ul><li>Masalan, QQS stavkasi yoki dollar kursi <code>H1</code> katagida turgan bo&#39;lsa, barcha mahsulotlar formulasida <code>$H$1</code> deb yoziladi.</li><li>Tezkor tugma: <code>F4</code> (Windows) yoki <code>Command + T</code> (Mac).</li></ul></li></ul><h3 id="_2-asosiy-matematik-va-statistik-funksiyalar" tabindex="-1">2. Asosiy matematik va statistik funksiyalar <a class="header-anchor" href="#_2-asosiy-matematik-va-statistik-funksiyalar" aria-label="Permalink to &quot;2. Asosiy matematik va statistik funksiyalar&quot;">​</a></h3><p>Barcha formulalar <code>=</code> belgisi bilan boshlanadi:</p><ul><li><code>=SUM(C2:C20)</code> — berilgan diapazondagi barcha sonlar yig&#39;indisi.</li><li><code>=AVERAGE(C2:C20)</code> — o&#39;rtacha arifmetik qiymat.</li><li><code>=COUNT(C2:C20)</code> — faqat sonlar yozilgan kataklar sonini sanaydi.</li><li><code>=COUNTA(A2:A20)</code> — bo&#39;sh bo&#39;lmagan (matn yoki son) barcha kataklarni sanaydi.</li><li><code>=MIN(C2:C20)</code> va <code>=MAX(C2:C20)</code> — eng kichik va eng katta qiymatni topadi.</li></ul><h3 id="_3-shartli-funksiyalar-conditional-functions" tabindex="-1">3. Shartli funksiyalar (Conditional Functions) <a class="header-anchor" href="#_3-shartli-funksiyalar-conditional-functions" aria-label="Permalink to &quot;3. Shartli funksiyalar (Conditional Functions)&quot;">​</a></h3><ul><li><strong><code>IF(shart, to&#39;g&#39;ri_bo&#39;lsa, noto&#39;g&#39;ri_bo&#39;lsa)</code>:</strong><code>=IF(D2&gt;=70, &quot;O&#39;tdi&quot;, &quot;Yiqildi&quot;)</code></li><li><strong><code>COUNTIF(diapazon, shart)</code>:</strong> Shartga to&#39;g&#39;ri keluvchi kataklar sonini sanaydi. <code>=COUNTIF(E2:E50, &quot;O&#39;tdi&quot;)</code> — nechta o&#39;quvchi o&#39;tganini sanaydi.</li><li><strong><code>SUMIF(tekshirish_diapazoni, shart, [yig&#39;indi_diapazoni])</code>:</strong> Faqat tanlangan shartga mos qatorlarning qiymatini qo&#39;shadi. <code>=SUMIF(B2:B50, &quot;Olma&quot;, D2:D50)</code> — faqat &quot;Olma&quot; sotuvlari yig&#39;indisini hisoblaydi.</li></ul><h3 id="_4-qidiruv-va-bog-lash-funksiyasi-xlookup" tabindex="-1">4. Qidiruv va bog&#39;lash funksiyasi: XLOOKUP <a class="header-anchor" href="#_4-qidiruv-va-bog-lash-funksiyasi-xlookup" aria-label="Permalink to &quot;4. Qidiruv va bog&#39;lash funksiyasi: XLOOKUP&quot;">​</a></h3><p>Eski <code>VLOOKUP</code> funksiyasi faqat o&#39;ng tomonga qidirar edi va ustun o&#39;zgarsa buzilar edi. Zamonaviy <code>XLOOKUP</code> esa juda qulay: <code>=XLOOKUP(qidirilayotgan_qiymat, qidiruv_ustuni, natija_ustuni, [topilmasa_nima_chiqsin])</code> Misol: Mijoz ID si (<code>A2</code>) bo&#39;yicha mijozlar bazasidan uning telefon raqamini topib keltirish: <code>=XLOOKUP(A2, Mijozlar!A:A, Mijozlar!C:C, &quot;Mijoz topilmadi&quot;)</code></p><h3 id="_5-formulalardagi-keng-tarqalgan-xatoliklar" tabindex="-1">5. Formulalardagi keng tarqalgan xatoliklar <a class="header-anchor" href="#_5-formulalardagi-keng-tarqalgan-xatoliklar" aria-label="Permalink to &quot;5. Formulalardagi keng tarqalgan xatoliklar&quot;">​</a></h3><ul><li><code>#VALUE!</code> — matematik amalga matn aralashib ketdi.</li><li><code>#N/A</code> — qidirilgan qiymat jadvalda mavjud emas.</li><li><code>#REF!</code> — formula havola qilgan katak yoki ustun o&#39;chirilgan.</li><li><code>#DIV/0!</code> — son nolga bo&#39;lindi.</li></ul><hr>',13))]),i("div",g,[i("h2",k,[l(o,{name:"file-text"}),a[6]||(a[6]=t(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-absolut-murojaat-bilan-qqs-hisoblash-oson" tabindex="-1">1-topshiriq. Absolut murojaat bilan QQS hisoblash (oson) <a class="header-anchor" href="#_1-topshiriq-absolut-murojaat-bilan-qqs-hisoblash-oson" aria-label="Permalink to &quot;1-topshiriq. Absolut murojaat bilan QQS hisoblash (oson)&quot;">​</a></h3><p>Jadvalda <code>Mahsulot</code>, <code>Baza narxi</code>, <code>Jami narx</code> ustunlari bor. <code>F1</code> katagida QQS stavkasi: <code>0.12</code> (12%) yozilgan. Barcha tovarlar uchun Jami narxni hisoblovchi formulani yozing va absolut murojaatni qo&#39;llang.</p><p><strong>Yechim:</strong> Formula <code>C2</code> katagiga yoziladi: <code>=B2 + (B2 * $F$1)</code> yoki <code>=B2 * (1 + $F$1)</code> Formulani pastga tortganda <code>B2</code> o&#39;zgaradi, lekin <code>$F$1</code> o&#39;zgarmaydi.</p><h3 id="_2-topshiriq-if-va-countif-orqali-sarhisob-o-rta" tabindex="-1">2-topshiriq. IF va COUNTIF orqali sarhisob (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-if-va-countif-orqali-sarhisob-o-rta" aria-label="Permalink to &quot;2-topshiriq. IF va COUNTIF orqali sarhisob (o&#39;rta)&quot;">​</a></h3><p>O&#39;quvchilar imtihon natijalari jadvali berilgan (<code>Ism</code>, <code>Ball</code>).</p><ol><li><code>Natija</code> ustunida balli 60 dan yuqori yoki teng bo&#39;lsa &quot;Muvaffaqiyatli&quot;, aks holda &quot;Qayta topshirish&quot; deb chiqaruvchi <code>IF</code> formulasini yozing.</li><li>Pastki alohida katakda nechta o&#39;quvchi &quot;Muvaffaqiyatli&quot; o&#39;tganini <code>COUNTIF</code> orqali hisoblang.</li></ol><p><strong>Yechim:</strong></p><ol><li><code>C2</code> katagiga: <code>=IF(B2&gt;=60, &quot;Muvaffaqiyatli&quot;, &quot;Qayta topshirish&quot;)</code></li><li>Alohida katakka: <code>=COUNTIF(C2:C25, &quot;Muvaffaqiyatli&quot;)</code></li></ol><h3 id="_3-topshiriq-xlookup-orqali-narxlarni-bog-lash-qiyin" tabindex="-1">3-topshiriq. XLOOKUP orqali narxlarni bog&#39;lash (qiyin) <a class="header-anchor" href="#_3-topshiriq-xlookup-orqali-narxlarni-bog-lash-qiyin" aria-label="Permalink to &quot;3-topshiriq. XLOOKUP orqali narxlarni bog&#39;lash (qiyin)&quot;">​</a></h3><p>Sizda ikkita alohida jadval bor:</p><ul><li>1-jadval (Buyurtmalar): <code>Buyurtma_ID</code>, <code>Mahsulot_Kodi</code>, <code>Miqdor</code></li><li>2-jadval (Narxlar ro&#39;yxati): <code>Mahsulot_Kodi</code>, <code>Mahsulot_Nomi</code>, <code>Narxi</code> Buyurtmalar jadvaliga <code>Narxi</code> va <code>Jami summa</code> ustunlarini qo&#39;shing va <code>XLOOKUP</code> orqali 2-jadvaldan narxni tortib keling.</li></ul><p><strong>Yechim:</strong></p><ol><li>Buyurtmalar jadvalidagi <code>D2</code> (Narxi) katagiga formula: <code>=XLOOKUP(B2, Narxlar!A:A, Narxlar!C:C, 0)</code></li><li><code>E2</code> (Jami summa) katagiga: <code>=C2 * D2</code> (Miqdor * Narxi).</li></ol><hr>',14))]),i("div",b,[i("h2",f,[l(o,{name:"file-text"}),a[9]||(a[9]=t(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Formulada nima uchun <code>$</code> belgisi ishlatiladi va uni qaysi tezkor tugma qo&#39;yadi? <ul><li><em>Javob:</em> Katak manzilini nusxalashda qotirish (absolut qilish) uchun, tezkor tugma <code>F4</code>.</li></ul></li><li><code>COUNT</code> va <code>COUNTA</code> funksiyalari o&#39;rtasidagi farq nimada? <ul><li><em>Javob:</em> <code>COUNT</code> faqat sonli kataklarni sanaydi, <code>COUNTA</code> esa bo&#39;sh bo&#39;lmagan barcha (matnli va sonli) kataklarni sanaydi.</li></ul></li><li><code>XLOOKUP</code> funksiyasi <code>VLOOKUP</code> ga nisbatan qanday 2 ta asosiy afzallikka ega? <ul><li><em>Javob:</em> Chap tomondagi ustunlarga ham qidira oladi va ustun raqamini sanashni talab qilmaydi.</li></ul></li></ol><hr>",2))]),i("div",y,[i("h2",v,[l(o,{name:"house"}),a[12]||(a[12]=t(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=r("<p>Excelda 7 ta mahsulotdan iborat jadval tuzing: <code>Nomi</code>, <code>Kategoriya</code>, <code>Narxi</code>, <code>Sotilgan soni</code>.</p><ol><li><code>SUMIF</code> orqali faqat &quot;Ichimliklar&quot; kategoriyasiga tegishli tovarlar tushumini hisoblang.</li><li><code>IF</code> funksiyasi yordamida sotilgan soni 50 tadan oshsa &quot;Ommabop&quot;, kam bo&#39;lsa &quot;Oddiy&quot; degan belgi chiqaring.</li></ol>",2))])])}const I=e(u,[["render",_]]);export{z as __pageData,I as default};
